        E(2, "Decorador simples", "Crie o decorador <code>@gritar</code> que deixa em MAIÚSCULAS o texto devolvido pela função, preservando o nome dela (<code>functools.wraps</code>).",
          'from functools import wraps\n\ndef gritar(f):\n    @wraps(f)\n    def envolve(*args, **kwargs):\n        return f(*args, **kwargs).upper()\n    return envolve\n\n@gritar\ndef saudacao(nome):\n    return f"olá, {nome}"', 'assert saudacao("ana") == "OLÁ, ANA"\nassert saudacao.__name__ == "saudacao", "Use @wraps(f)"', ["Um decorador recebe a função e devolve outra", "@wraps(f) preserva o nome"]),
        E(2, "Torre de Hanói", "Crie <code>hanoi(n, origem=\"A\", destino=\"C\", aux=\"B\")</code> que devolve a lista de movimentos <code>(de, para)</code>. Para n discos são 2ⁿ − 1 movimentos.",
          'def hanoi(n, origem="A", destino="C", aux="B"):\n    if n == 0:\n        return []\n    return hanoi(n - 1, origem, aux, destino) + [(origem, destino)] + hanoi(n - 1, aux, destino, origem)', 'assert hanoi(2) == [("A", "B"), ("A", "C"), ("B", "C")]\nassert len(hanoi(5)) == 31 and hanoi(1) == [("A", "C")]', ["Mova n−1 para o auxiliar, o maior para o destino, n−1 para o destino", "Caso base: n == 0"]),
        E(2, "Busca binária recursiva", "Crie <code>busca(lista, alvo, esq=0, dir=None)</code> recursiva que devolve o índice ou −1 (lista ordenada).",
          'def busca(lista, alvo, esq=0, dir=None):\n    if dir is None:\n        dir = len(lista) - 1\n    if esq > dir:\n        return -1\n    meio = (esq + dir) // 2\n    if lista[meio] == alvo:\n        return meio\n    if lista[meio] < alvo:\n        return busca(lista, alvo, meio + 1, dir)\n    return busca(lista, alvo, esq, meio - 1)', 'l = [1, 3, 5, 7, 9, 11]\nassert busca(l, 7) == 3 and busca(l, 1) == 0 and busca(l, 4) == -1 and busca([], 1) == -1', ["Compare com o meio e descarte metade", "Caso base: esq > dir"]),
